mapper.select:
SELECT
, b.model_name
FROM bt_ai_model a
LEFT JOIN bt_library_large_model b ON a.model_id = b.model_id AND b.status_cd = '00A'
WHERE a.space_id = #{spaceId}
  AND a.bot_id = #{botId}
  AND a.creator_id = #{userId}
  AND a.model_type = #{modelType}
  AND a.status_cd = '00A'
